func (r *AIControlSummaryResolver) VisibleFailures(ctx context.Context, obj *aicontrolsummary.Summary) ([]*aicontrolsummary.ProviderFailure, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceAgentControl, permission.OpRead)
	if err != nil {
		return nil, err
	}

	visible, err := r.AiControlSummaryService.VisibleFailures(ctx, &services.VisibleFailuresRequest{
		TenantInfo: base.TenantInfo(authCtx),
		UserID:     authCtx.UserID,
		Failing:    obj.Facts.Failing,
	})
	if err != nil {
		return nil, err
	}

	out := make([]*aicontrolsummary.ProviderFailure, len(visible))
	for idx := range visible {
		out[idx] = &visible[idx]
	}
	return out, nil
}

func (r *MutationResolver) DismissAIProviderFailure(ctx context.Context, providerID string, lastFailureAt int) (bool, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceAgentControl, permission.OpRead)
	if err != nil {
		return false, err
	}

	id, err := pulid.MustParse(providerID)
	if err != nil {
		return false, err
	}

	if err = r.AiControlSummaryService.DismissFailure(ctx, &services.ProviderFailureDismissal{
		TenantInfo: base.TenantInfo(authCtx),
		UserID:     authCtx.UserID,
		ProviderID: id,
		FailureAt:  int64(lastFailureAt),
	}); err != nil {
		return false, err
	}
	return true, nil
}

